<template>
 <details id="bark-cloud-alerts" class="bark-cloud">
  <summary><span><AppIcon name="bell" /><strong>{{ c('title') }}</strong><small>{{ c('tag') }}</small></span><span class="bark-plus">+</span></summary>
  <div class="bark-content">
   <div class="bark-heading"><div><h3>{{ c('summary') }}</h3><p>{{ c('intro') }}</p></div><span class="bark-badge" :class="{connected:subscription}">{{ subscription?c(active?'bound':'paused'):c('unbound') }}</span></div>
   <div v-if="!subscription" class="bark-address"><label for="bark-address">{{ c('address') }}</label><div class="bark-address-input"><component :is="'input'" id="bark-address" class="bark-native-address" :type="reveal?'text':'password'" :value="address" :placeholder="c('placeholder')" autocomplete="off" autocapitalize="off" spellcheck="false" :disabled="busy" :aria-label="c('address')" @input="address=$event.target.value;bindId=''" @keydown.enter="connect" /><WebButton class="base-button" :aria-label="c(reveal?'hide':'show')" @click="reveal=!reveal">{{ c(reveal?'hide':'show') }}</WebButton></div><p>{{ c('privacy') }}</p></div>
   <div v-else class="bark-connected"><span>{{ c('device') }} <b>{{ subscription.deviceHint }}</b></span><span v-if="dirty" class="bark-dirty">{{ c('unsaved') }}</span></div>
   <div class="bark-preferences">
    <div class="bark-setting"><div><strong>{{ c('reset') }}</strong><p>{{ c('resetHelp') }}</p></div><WebButton class="base-button bark-toggle" :class="{on:form.resetAlerts}" role="switch" :aria-checked="form.resetAlerts" :aria-label="c('reset')" :disabled="busy" @click="edit('resetAlerts',!form.resetAlerts)"><span></span></WebButton></div>
    <div class="bark-setting"><div><strong>{{ c('forecast') }}</strong><p>{{ c('forecastHelp') }}</p></div><WebButton class="base-button bark-toggle" :class="{on:form.forecastAlerts}" role="switch" :aria-checked="form.forecastAlerts" :aria-label="c('forecast')" :disabled="busy" @click="edit('forecastAlerts',!form.forecastAlerts)"><span></span></WebButton></div>
    <div class="bark-threshold"><div><label for="bark-threshold">{{ c('threshold') }}</label><strong>{{ form.threshold }}%</strong></div><component :is="'input'" id="bark-threshold" class="bark-native-range" type="range" min="40" max="90" step="5" :value="form.threshold" :disabled="busy||!form.forecastAlerts" :aria-label="c('threshold')" @input="edit('threshold',Number($event.target.value))" /><div class="bark-ticks"><span v-for="v in [40,50,60,70,80,90]" :key="v">{{ v }}%</span></div><p>{{ c('thresholdHelp') }}</p></div>
    <div class="bark-setting bark-language"><strong>{{ c('language') }}</strong><div><WebButton v-for="lang in ['zh','en']" :key="lang" class="base-button" :class="{selected:form.language===lang}" :aria-pressed="form.language===lang" :disabled="busy" @click="edit('language',lang)">{{ c(lang) }}</WebButton></div></div>
   </div>
   <div class="bark-actions"><WebButton class="base-button bark-primary" :disabled="busy||(!subscription&&!address.trim())||(subscription&&!dirty)" @click="subscription?save():connect()">{{ c(busy?'saving':subscription?'save':'bind') }}</WebButton><WebButton v-if="subscription" class="base-button bark-secondary" :disabled="busy||cooling" @click="testPush">{{ c('test') }}</WebButton><WebButton v-if="subscription" class="base-button bark-text-button" :disabled="busy" @click="refresh">{{ c('refresh') }}</WebButton></div>
   <p v-if="subscription&&cooling" class="bark-help">{{ c('cooldown') }}</p>
   <p v-if="notice" class="bark-feedback" :class="{error:noticeError}" role="status">{{ c(notice) }}</p>
   <p v-if="!persistent" class="bark-feedback">{{ c('persistent') }}</p>
   <div v-if="subscription" class="bark-receipts"><h4>{{ c('receiptTitle') }}</h4><p v-if="!subscription.receipts.length">{{ c('empty') }}</p><div v-for="(r,i) in subscription.receipts" :key="i" class="bark-receipt"><span>{{ c(r.kind+'Kind') }}</span><span>{{ c(r.state) }}</span><time>{{ time(r.updatedAt) }}</time></div><p>{{ c('receiptHelp') }}</p></div>
   <div class="bark-notes"><p>{{ c('history') }}</p><p>{{ c('limits') }}</p><p>{{ c('rebind') }}</p></div>
   <div v-if="subscription" class="bark-unsubscribe"><template v-if="confirmDelete"><p>{{ c('deleteHelp') }}</p><div><WebButton class="base-button bark-danger" :disabled="busy" @click="unsubscribe">{{ c('confirmDelete') }}</WebButton><WebButton class="base-button bark-text-button" :disabled="busy" @click="confirmDelete=false">{{ c('cancel') }}</WebButton></div></template><WebButton v-else class="base-button bark-text-button" :disabled="busy" @click="confirmDelete=true">{{ c('unsubscribe') }}</WebButton></div>
  </div>
 </details>
</template>
<script setup>
import {ref,reactive,computed,watch,onMounted,onUnmounted} from 'vue';
import AppIcon from './AppIcon.vue';
import WebButton from './WebButton.vue';
import {createVisitorBarkClient} from '../lib/visitor-bark-client.mjs';
import {barkMessages} from '../lib/bark-i18n.mjs';
import {config} from '../config';
const props=defineProps({language:{type:String,default:'zh'}}),c=key=>barkMessages[props.language]?.[key]||barkMessages[props.language]?.unavailable;
const client=createVisitorBarkClient({base:config.apiBase||'https://pulse-radar-api.chqua75.workers.dev/api',storage:{getItem:key=>uni.getStorageSync(key),setItem:(key,value)=>uni.setStorageSync(key,value),removeItem:key=>uni.removeStorageSync(key)}});
const address=ref(''),reveal=ref(false),busy=ref(false),subscription=ref(null),notice=ref(''),noticeError=ref(false),persistent=ref(true),confirmDelete=ref(false),now=ref(Date.now());
const form=reactive({resetAlerts:true,forecastAlerts:true,threshold:60,language:props.language});
let bindId='',testId='',edits=0,generation=0,pollTimer,tick,polls=0,disposed=false;
const dirty=computed(()=>Boolean(subscription.value)&&JSON.stringify(form)!==JSON.stringify(subscription.value.settings));
const active=computed(()=>subscription.value?.settings.resetAlerts||subscription.value?.settings.forecastAlerts);
const cooling=computed(()=>Date.parse(subscription.value?.testAvailableAt)>now.value);
const time=value=>new Intl.DateTimeFormat(props.language==='zh'?'zh-CN':'en-GB',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(value));
function edit(key,value){form[key]=value;edits++;notice.value='';}
function apply(value,hydrate=true){subscription.value=value;if(value&&hydrate)Object.assign(form,value.settings);}
function feedback(code,error=false){notice.value=code;noticeError.value=error;}
async function operation(action){if(busy.value)return;generation++;busy.value=true;notice.value='';try{await action();}catch(error){if(error.code==='session_expired')subscription.value=null;feedback(error.code||'unavailable',true);}finally{busy.value=false;}}
function connect(){return operation(async()=>{bindId||=crypto.randomUUID();const state=await client.bind(address.value.trim(),{...form},bindId);apply(state);address.value='';reveal.value=false;bindId='';persistent.value=client.isPersistent();feedback('binding_saved');});}
function save(){return operation(async()=>{apply(await client.save({...form},subscription.value.version));feedback('preferences_saved');});}
function refresh(){return operation(async()=>{const revision=edits,value=await client.load();apply(value,revision===edits&&!dirty.value);});}
function testPush(){return operation(async()=>{testId||=crypto.randomUUID();await client.test(testId);feedback('test_queued');testId='';const revision=edits;apply(await client.load(),revision===edits&&!dirty.value);polls=0;schedulePoll();});}
function schedulePoll(){clearTimeout(pollTimer);if(disposed||polls>=8)return;pollTimer=setTimeout(async()=>{polls++;const epoch=generation;if(!busy.value){try{const revision=edits,value=await client.load();if(!disposed&&epoch===generation&&client.hasSession())apply(value,revision===edits&&!dirty.value);}catch(error){if(epoch===generation&&error.code==='session_expired'){subscription.value=null;return;}}}if(!disposed&&subscription.value?.receipts.some(r=>r.kind==='test'&&['pending','retry'].includes(r.state)))schedulePoll();},15000);}
function unsubscribe(){return operation(async()=>{await client.unsubscribe();apply(null);confirmDelete.value=false;clearTimeout(pollTimer);feedback('unsubscribed');});}
watch(()=>props.language,lang=>{if(!subscription.value)form.language=lang;});
onMounted(()=>{if(client.hasSession())refresh();tick=setInterval(()=>now.value=Date.now(),30000);});
onUnmounted(()=>{disposed=true;clearTimeout(pollTimer);clearInterval(tick);});
</script>
<style>
.bark-cloud{margin-top:28px;border:1px solid #d9e2fc;border-radius:16px;background:#fff;color:#1c202b;overflow:hidden}.bark-cloud summary{list-style:none;display:flex;align-items:center;justify-content:space-between;gap:16px;padding:23px 25px;cursor:pointer;background:linear-gradient(110deg,#f0f4ff,#fff)}.bark-cloud summary::-webkit-details-marker{display:none}.bark-cloud summary>span:first-child{display:grid;grid-template-columns:20px minmax(0,1fr);align-items:start;gap:5px 12px;min-width:0}.bark-cloud summary>span:first-child>.app-icon{grid-column:1;grid-row:1;margin-top:2px}.bark-cloud summary strong{grid-column:2;grid-row:1;line-height:1.5}.bark-cloud summary small{grid-column:2;grid-row:2}.bark-cloud summary strong{font-size:16px}.bark-cloud summary small{font-size:12px;color:#606a82}.bark-plus{font-size:24px;color:#697aa3}.bark-cloud[open] .bark-plus{transform:rotate(45deg)}.bark-content{padding:26px}.bark-heading{display:flex;align-items:flex-start;gap:16px;justify-content:space-between}.bark-content h3{font-size:19px;line-height:1.45;margin:0 0 8px}.bark-content p{font-size:12px;line-height:1.75;color:#636c80;margin:6px 0}.bark-badge{border-radius:99px;padding:5px 10px;font-size:11px;max-width:100%;line-height:1.5;white-space:normal;background:#f0f1f3;color:#626b7f}.bark-badge.connected{color:#3756ac;background:#edf2ff}.bark-address{margin:24px 0}.bark-address label,.bark-threshold label{font-size:13px;font-weight:600}.bark-address-input{display:flex;border:1px solid #d4daea;border-radius:9px;margin:10px 0;min-height:45px;overflow:hidden}.bark-address-input .bark-native-address{border:0;outline:none;padding:12px;min-width:0;flex:1;width:100%;font:inherit;font-size:13px;background:white;color:#1c202b}.bark-address-input:focus-within{outline:2px solid #8da4ef;outline-offset:1px}.bark-address-input .base-button{font-size:11px;padding:0 12px;white-space:nowrap;color:#405a9c;background:#f5f7fd}.bark-connected{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;margin:22px 0;font-size:12px;color:#5a647b}.bark-connected b{letter-spacing:1px;color:#263c6c}.bark-dirty{color:#94642a}.bark-preferences{display:grid;grid-template-columns:1fr 1fr;gap:0 32px;margin-top:18px}.bark-setting{display:flex;justify-content:space-between;gap:20px;align-items:center;padding:19px 0;border-bottom:1px solid #eceff5}.bark-setting strong{font-size:13px}.bark-setting p{margin-bottom:0}.bark-toggle{flex:none;width:42px;height:25px;border-radius:20px!important;background:#d6dbe7!important;padding:3px!important;justify-content:flex-start!important}.bark-toggle>span{display:block;width:19px;height:19px;border-radius:50%;background:#fff;box-shadow:0 1px 3px #0002;transition:transform .15s}.bark-toggle.on{background:#3e63dd!important}.bark-toggle.on>span{transform:translateX(17px)}.bark-toggle:focus-visible,.bark-actions .base-button:focus-visible{outline:2px solid #8da4ef;outline-offset:3px}.bark-threshold{padding:22px 0}.bark-threshold>div:first-child{display:flex;justify-content:space-between;align-items:center}.bark-threshold strong{font-size:24px;font-weight:500;color:#3e63dd}.bark-threshold .bark-native-range{display:block;width:100%;margin:18px 0 8px;accent-color:#3e63dd;min-height:25px}.bark-threshold .bark-native-range:disabled{opacity:.4}.bark-ticks{display:flex;justify-content:space-between;color:#7b8598;font-size:10px}.bark-language{align-self:start}.bark-language>div{display:flex;border:1px solid #dfe4ef;border-radius:7px;overflow:hidden;flex:none}.bark-language .base-button{font-size:12px;padding:7px 10px;color:#727b90}.bark-language .base-button.selected{background:#edf2ff;color:#3157b7}.bark-actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-top:18px}.bark-actions .base-button,.bark-unsubscribe .base-button{font-size:12px;min-height:40px;border-radius:8px;padding:9px 15px}.bark-primary{background:#243b74!important;color:white!important}.bark-secondary{border:1px solid #d7dfef!important;color:#345494!important;background:white!important}.bark-text-button{color:#5c6d91!important;text-decoration:underline;text-underline-offset:4px}.bark-cloud .base-button:disabled{opacity:.45;cursor:default}.bark-feedback{padding:11px 14px;border-radius:8px;background:#eef3ff;color:#35548f!important;margin-top:15px!important}.bark-feedback.error{background:#fff4ee;color:#96512d!important}.bark-receipts{margin-top:25px;padding:18px;border:1px solid #e4e8f1;border-radius:10px}.bark-receipts h4{font-size:13px;margin:0 0 10px}.bark-receipt{display:grid;grid-template-columns:1fr 1fr auto;gap:12px;padding:9px 0;font-size:12px;border-bottom:1px solid #eef0f6;color:#43516d}.bark-receipt time{font-size:11px;color:#788397}.bark-notes{margin-top:22px}.bark-unsubscribe{margin-top:18px;border-top:1px solid #eceff5;padding-top:15px}.bark-unsubscribe>div{display:flex;gap:12px;flex-wrap:wrap}.bark-danger{background:#fff3ef!important;border:1px solid #e9c4b7!important;color:#a44a30!important}.bark-help{margin-top:10px!important}@media(max-width:640px){.bark-cloud summary{padding:20px}.bark-cloud summary small{flex-basis:100%;margin-left:0}.bark-content{padding:20px}.bark-heading{flex-direction:column;gap:10px}.bark-preferences{grid-template-columns:1fr}.bark-setting{gap:14px}.bark-actions{gap:10px}.bark-primary{width:100%;justify-content:center!important}.bark-secondary{flex:1;justify-content:center!important}.bark-receipts{padding:13px}.bark-receipt{grid-template-columns:1fr 1fr;gap:6px}.bark-receipt time{grid-column:1/-1}.bark-address-input .base-button{max-width:90px;white-space:normal!important;line-height:1.4}.bark-language{padding-top:15px}.bark-content h3{font-size:17px}}
</style>
